//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_input(value: *mut bool) -> bool;
  fn get_input_num_invalid() -> u64;
  fn get_manualActuatorInput(value: *mut bool) -> bool;
  fn get_manualActuatorInput_num_invalid() -> u64;
  fn put_output(value: *mut bool) -> bool;
}

pub fn unsafe_get_input() -> bool
{
  unsafe {
    let value: *mut bool = &mut false;
    get_input(value);
    return *value;
  }
}

pub fn unsafe_get_input_num_invalid() -> u64
{
  unsafe {
    return get_input_num_invalid();
  }
}

pub fn unsafe_get_manualActuatorInput() -> bool
{
  unsafe {
    let value: *mut bool = &mut false;
    get_manualActuatorInput(value);
    return *value;
  }
}

pub fn unsafe_get_manualActuatorInput_num_invalid() -> u64
{
  unsafe {
    return get_manualActuatorInput_num_invalid();
  }
}

pub fn unsafe_put_output(value: &bool) -> bool
{
  unsafe {
    return put_output(value as *const bool as *mut bool);
  }
}

//////////////////////////////////////////////////////////////////////////////////
// Testing Versions
//////////////////////////////////////////////////////////////////////////////////

#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_input: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref IN_manualActuatorInput: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref OUT_output: Mutex<Option<bool>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_input.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_manualActuatorInput.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_output.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_input(value: *mut bool) -> bool
{
  unsafe {
    let guard = IN_input.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn get_input_num_invalid() -> u64
{
  return 0;
}

#[cfg(test)]
pub fn get_manualActuatorInput(value: *mut bool) -> bool
{
  unsafe {
    let guard = IN_manualActuatorInput.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn get_manualActuatorInput_num_invalid() -> u64
{
  return 0;
}

#[cfg(test)]
pub fn put_output(value: *mut bool) -> bool
{
  unsafe {
    *OUT_output.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
